     /* ======================================================================
     * SECTION 32
     * Mathematical Utility Functions
     * ====================================================================== */

    function toFiniteNumber(
        value,
        fallback = 0
    ) {

        if (
            typeof value === "number" &&
            Number.isFinite(value)
        ) {
            return value;
        }

        if (
            typeof value === "string" &&
            value.trim() !== ""
        ) {

            const parsed =
                Number(value);

            if (
                Number.isFinite(parsed)
            ) {
                return parsed;
            }
        }

        return fallback;
    }

    function clampNumber(
        value,
        minimum = 0,
        maximum = 100,
        fallback = minimum
    ) {

        const number =
            toFiniteNumber(
                value,
                fallback
            );

        return Math.min(
            maximum,
            Math.max(
                minimum,
                number
            )
        );
    }

    function clampPercentage(
        value,
        fallback = 0
    ) {

        return clampNumber(
            value,
            0,
            100,
            fallback
        );
    }

    function roundNumber(
        value,
        decimals = 2
    ) {

        const number =
            toFiniteNumber(
                value,
                0
            );

        const precision =
            clampNumber(
                decimals,
                0,
                10,
                2
            );

        const factor =
            10 ** precision;

        return (
            Math.round(
                number *
                factor
            ) /
            factor
        );
    }

    function safeDivide(
        numerator,
        denominator,
        fallback = 0
    ) {

        const safeNumerator =
            toFiniteNumber(
                numerator,
                0
            );

        const safeDenominator =
            toFiniteNumber(
                denominator,
                0
            );

        if (
            safeDenominator === 0
        ) {
            return fallback;
        }

        return (
            safeNumerator /
            safeDenominator
        );
    }

    function calculateAverage(
        values = []
    ) {

        if (
            !Array.isArray(values) ||
            values.length === 0
        ) {
            return 0;
        }

        const validValues =
            values
                .map((value) =>
                    toFiniteNumber(
                        value,
                        null
                    )
                )
                .filter((value) =>
                    value !== null
                );

        if (
            validValues.length === 0
        ) {
            return 0;
        }

        const total =
            validValues.reduce(
                (
                    accumulator,
                    value
                ) =>
                    accumulator +
                    value,
                0
            );

        return (
            total /
            validValues.length
        );
    }

    function calculateWeightedAverage(
        items = [],
        valueKey = "value",
        weightKey = "weight"
    ) {

        if (
            !Array.isArray(items) ||
            items.length === 0
        ) {
            return 0;
        }

        let weightedTotal =
            0;

        let totalWeight =
            0;

        for (
            const item of items
        ) {

            if (
                !item ||
                typeof item !== "object"
            ) {
                continue;
            }

            const value =
                toFiniteNumber(
                    item[valueKey],
                    null
                );

            const weight =
                Math.max(
                    0,
                    toFiniteNumber(
                        item[weightKey],
                        0
                    )
                );

            if (
                value === null ||
                weight <= 0
            ) {
                continue;
            }

            weightedTotal +=
                value *
                weight;

            totalWeight +=
                weight;
        }

        if (
            totalWeight <= 0
        ) {
            return 0;
        }

        return (
            weightedTotal /
            totalWeight
        );
    }

    function calculateStandardDeviation(
        values = []
    ) {

        if (
            !Array.isArray(values) ||
            values.length < 2
        ) {
            return 0;
        }

        const validValues =
            values
                .map((value) =>
                    toFiniteNumber(
                        value,
                        null
                    )
                )
                .filter((value) =>
                    value !== null
                );

        if (
            validValues.length < 2
        ) {
            return 0;
        }

        const average =
            calculateAverage(
                validValues
            );

        const variance =
            validValues.reduce(
                (
                    accumulator,
                    value
                ) =>
                    accumulator +
                    (
                        value -
                        average
                    ) ** 2,
                0
            ) /
            validValues.length;

        return Math.sqrt(
            variance
        );
    }

    /* ======================================================================
     * SECTION 33
     * Horizon Helpers
     * ====================================================================== */

    function normalizeForecastHorizon(
        horizon
    ) {

        const numericHorizon =
            Math.round(
                toFiniteNumber(
                    horizon,
                    6
                )
            );

        if (
            FORECAST_HORIZONS_HOURS.includes(
                numericHorizon
            )
        ) {
            return numericHorizon;
        }

        let nearest =
            FORECAST_HORIZONS_HOURS[0];

        let nearestDifference =
            Math.abs(
                numericHorizon -
                nearest
            );

        for (
            const candidate of
            FORECAST_HORIZONS_HOURS
        ) {

            const difference =
                Math.abs(
                    numericHorizon -
                    candidate
                );

            if (
                difference <
                nearestDifference
            ) {

                nearest =
                    candidate;

                nearestDifference =
                    difference;
            }
        }

        return nearest;
    }

    function getForecastHorizonKey(
        horizon
    ) {

        const normalizedHorizon =
            normalizeForecastHorizon(
                horizon
            );

        return `h${normalizedHorizon}`;
    }

    function getForecastHorizonLabel(
        horizon,
        language = "ar"
    ) {

        const key =
            getForecastHorizonKey(
                horizon
            );

        const labels =
            FORECAST_HORIZON_LABELS[
                key
            ];

        if (
            !labels
        ) {
            return key;
        }

        return (
            language === "en"
                ? labels.en
                : labels.ar
        );
    }

    /* ======================================================================
     * SECTION 34
     * Source Availability Normalization
     * ====================================================================== */

    function normalizeSourceAvailability(
        source = {}
    ) {

        if (
            !source ||
            typeof source !== "object"
        ) {
            return false;
        }

        if (
            source.available === false ||
            source.enabled === false
        ) {
            return false;
        }

        if (
            source.available === true ||
            source.ok === true ||
            source.active === true
        ) {
            return true;
        }

        const status =
            String(
                source.status ??
                ""
            )
                .trim()
                .toUpperCase();

        return [
            "ACTIVE",
            "AVAILABLE",
            "CONNECTED",
            "VERIFIED",
            "SUPPORTED",
            "CACHED",
            "SIMULATION"
        ].includes(
            status
        );
    }

    function normalizeSourceAgeMinutes(
        source = {}
    ) {

        const directAge =
            toFiniteNumber(
                source.ageMinutes ??
                source.dataAgeMinutes ??
                source.frameAgeMinutes,
                null
            );

        if (
            directAge !== null
        ) {
            return Math.max(
                0,
                directAge
            );
        }

        const timestamp =
            source.timestamp ??
            source.updatedAt ??
            source.issuedAt ??
            null;

        if (
            !timestamp
        ) {
            return Number.POSITIVE_INFINITY;
        }

        const timestampMs =
            new Date(
                timestamp
            ).getTime();

        if (
            !Number.isFinite(
                timestampMs
            )
        ) {
            return Number.POSITIVE_INFINITY;
        }

        return Math.max(
            0,
            (
                Date.now() -
                timestampMs
            ) /
            MILLISECONDS_PER_MINUTE
        );
    }

    /* ======================================================================
     * SECTION 35
     * Source Freshness Scoring
     * ====================================================================== */

    function calculateSourceFreshnessScore(
        sourceKey,
        source = {}
    ) {

        const limits =
            SOURCE_FRESHNESS_LIMITS_MINUTES[
                sourceKey
            ];

        if (
            !limits
        ) {
            return 50;
        }

        const ageMinutes =
            normalizeSourceAgeMinutes(
                source
            );

        if (
            !Number.isFinite(
                ageMinutes
            )
        ) {
            return 0;
        }

        if (
            ageMinutes <=
            limits.fresh
        ) {
            return 100;
        }

        if (
            ageMinutes <=
            limits.acceptable
        ) {

            const range =
                limits.acceptable -
                limits.fresh;

            const elapsed =
                ageMinutes -
                limits.fresh;

            return clampPercentage(
                100 -
                safeDivide(
                    elapsed,
                    range,
                    0
                ) *
                20,
                80
            );
        }

        if (
            ageMinutes <=
            limits.stale
        ) {

            const range =
                limits.stale -
                limits.acceptable;

            const elapsed =
                ageMinutes -
                limits.acceptable;

            return clampPercentage(
                80 -
                safeDivide(
                    elapsed,
                    range,
                    0
                ) *
                45,
                35
            );
        }

        return 10;
    }

    /* ======================================================================
     * SECTION 36
     * Source Quality Scoring
     * ====================================================================== */

    function calculateSourceQualityScore(
        sourceKey,
        source = {}
    ) {

        if (
            !normalizeSourceAvailability(
                source
            )
        ) {
            return 0;
        }

        const freshness =
            calculateSourceFreshnessScore(
                sourceKey,
                source
            );

        const reliability =
            clampPercentage(
                (
                    toFiniteNumber(
                        source.reliability ??
                        source.trust,
                        0.7
                    )
                ) <= 1
                    ? toFiniteNumber(
                        source.reliability ??
                        source.trust,
                        0.7
                    ) * 100
                    : toFiniteNumber(
                        source.reliability ??
                        source.trust,
                        70
                    ),
                70
            );

        const confidence =
            clampPercentage(
                source.confidence ??
                source.finalConfidence ??
                60,
                60
            );

        const completeness =
            clampPercentage(
                source.completeness ??
                source.coverage ??
                source.dataCompleteness ??
                70,
                70
            );

        const technicalHealth =
            clampPercentage(
                source.technicalHealth ??
                source.healthScore ??
                80,
                80
            );

        let quality =
            freshness *
                0.30 +

            reliability *
                0.25 +

            confidence *
                0.20 +

            completeness *
                0.15 +

            technicalHealth *
                0.10;

        if (
            source.simulated === true
        ) {
            quality *=
                0.60;
        }

        if (
            source.error
        ) {
            quality *=
                0.50;
        }

        return clampPercentage(
            quality,
            0
        );
    }

    /* ======================================================================
     * SECTION 37
     * Rain Probability Extraction
     * ====================================================================== */

    function extractSourceRainProbability(
        sourceKey,
        source = {},
        horizonHours = 6
    ) {

        const horizon =
            normalizeForecastHorizon(
                horizonHours
            );

        const horizonKey =
            getForecastHorizonKey(
                horizon
            );

        const horizonForecast =
            source.forecast?.[
                horizonKey
            ] ??
            source.forecasts?.[
                horizonKey
            ] ??
            source.horizons?.[
                horizonKey
            ] ??
            source.hourlyForecast?.[
                horizon
            ] ??
            null;

        if (
            horizonForecast &&
            typeof horizonForecast === "object"
        ) {

            const directHorizonProbability =
                horizonForecast.rainProbability ??
                horizonForecast.probability ??
                horizonForecast.precipitationProbability ??
                horizonForecast.precipitation_probability;

            if (
                directHorizonProbability !==
                undefined
            ) {
                return clampPercentage(
                    directHorizonProbability,
                    0
                );
            }
        }

        const directProbability =
            source.rainProbability ??
            source.probability ??
            source.precipitationProbability ??
            source.precipitation_probability ??
            source.rainRisk ??
            source.signalScore ??
            null;

        if (
            directProbability !==
            null
        ) {

            let probability =
                clampPercentage(
                    directProbability,
                    0
                );

            if (
                sourceKey === "radar" ||
                sourceKey === "stormPath" ||
                sourceKey === "rainArrival" ||
                sourceKey === "lightning"
            ) {

                const decayFactor =
                    Math.max(
                        0.10,
                        1 -
                        (
                            horizon /
                            84
                        )
                    );

                probability *=
                    decayFactor;
            }

            return clampPercentage(
                probability,
                0
            );
        }

        return 0;
    }

    /* ======================================================================
     * SECTION 38
     * Rainfall Amount Extraction
     * ====================================================================== */

    function extractSourceRainfallAmount(
        source = {},
        horizonHours = 6
    ) {

        const horizon =
            normalizeForecastHorizon(
                horizonHours
            );

        const horizonKey =
            getForecastHorizonKey(
                horizon
            );

        const horizonForecast =
            source.forecast?.[
                horizonKey
            ] ??
            source.forecasts?.[
                horizonKey
            ] ??
            source.horizons?.[
                horizonKey
            ] ??
            null;

        if (
            horizonForecast &&
            typeof horizonForecast === "object"
        ) {

            const horizonAmount =
                horizonForecast.rainfallMm ??
                horizonForecast.rainAmount ??
                horizonForecast.precipitation ??
                horizonForecast.accumulationMm;

            if (
                horizonAmount !==
                undefined
            ) {
                return Math.max(
                    0,
                    toFiniteNumber(
                        horizonAmount,
                        0
                    )
                );
            }
        }

        const directAmount =
            source.rainfallMm ??
            source.rainAmount ??
            source.precipitation ??
            source.accumulationMm ??
            source.rain ??
            0;

        return Math.max(
            0,
            toFiniteNumber(
                directAmount,
                0
            )
        );
    }

    /* ======================================================================
     * SECTION 39
     * Dynamic Source Weight
     * ====================================================================== */

    function calculateDynamicSourceWeight(
        sourceKey,
        source,
        horizonHours
    ) {

        const horizonKey =
            getForecastHorizonKey(
                horizonHours
            );

        const relevanceWeights =
            HORIZON_SOURCE_RELEVANCE[
                horizonKey
            ] ??
            DEFAULT_SOURCE_WEIGHTS;

        const baseWeight =
            toFiniteNumber(
                relevanceWeights[
                    sourceKey
                ],
                DEFAULT_SOURCE_WEIGHTS[
                    sourceKey
                ] ?? 0
            );

        if (
            baseWeight <= 0 ||
            !normalizeSourceAvailability(
                source
            )
        ) {
            return 0;
        }

        const qualityScore =
            calculateSourceQualityScore(
                sourceKey,
                source
            );

        const confidenceScore =
            clampPercentage(
                source.confidence ??
                source.finalConfidence ??
                60,
                60
            );

        const freshnessScore =
            calculateSourceFreshnessScore(
                sourceKey,
                source
            );

        const qualityFactor =
            qualityScore /
            100;

        const confidenceFactor =
            confidenceScore /
            100;

        const freshnessFactor =
            freshnessScore /
            100;

        let dynamicWeight =
            baseWeight *
            (
                qualityFactor *
                    0.45 +

                confidenceFactor *
                    0.30 +

                freshnessFactor *
                    0.25
            );

        if (
            source.simulated === true
        ) {
            dynamicWeight *=
                0.50;
        }

        if (
            source.official === true
        ) {
            dynamicWeight *=
                1.05;
        }

        return Math.max(
            0,
            dynamicWeight
        );
    }

    /* ======================================================================
     * SECTION 40
     * Source Weight Normalization
     * ====================================================================== */

    function normalizeSourceWeights(
        weightedSources = []
    ) {

        if (
            !Array.isArray(
                weightedSources
            ) ||
            weightedSources.length === 0
        ) {
            return [];
        }

        const totalWeight =
            weightedSources.reduce(
                (
                    accumulator,
                    source
                ) =>
                    accumulator +
                    Math.max(
                        0,
                        toFiniteNumber(
                            source.weight,
                            0
                        )
                    ),
                0
            );

        if (
            totalWeight <= 0
        ) {
            return weightedSources.map(
                (source) => ({
                    ...source,
                    normalizedWeight:
                        0
                })
            );
        }

        return weightedSources.map(
            (source) => ({
                ...source,

                normalizedWeight:
                    Math.max(
                        0,
                        toFiniteNumber(
                            source.weight,
                            0
                        )
                    ) /
                    totalWeight
            })
        );
    }

    /* ======================================================================
     * SECTION 41
     * Multi-Source Probability Fusion
     * ====================================================================== */

    function calculateFusedRainProbability(
        sources = {},
        horizonHours = 6
    ) {

        const weightedSources =
            [];

        for (
            const sourceKey of
            Object.keys(
                DEFAULT_SOURCE_WEIGHTS
            )
        ) {

            const source =
                sources[
                    sourceKey
                ];

            if (
                !source ||
                !normalizeSourceAvailability(
                    source
                )
            ) {
                continue;
            }

            const probability =
                extractSourceRainProbability(
                    sourceKey,
                    source,
                    horizonHours
                );

            const weight =
                calculateDynamicSourceWeight(
                    sourceKey,
                    source,
                    horizonHours
                );

            const quality =
                calculateSourceQualityScore(
                    sourceKey,
                    source
                );

            if (
                weight <= 0
            ) {
                continue;
            }

            weightedSources.push({

                sourceKey,

                probability,

                weight,

                quality,

                confidence:
                    clampPercentage(
                        source.confidence ??
                        source.finalConfidence ??
                        60,
                        60
                    ),

                simulated:
                    source.simulated ===
                    true

            });
        }

        const normalizedSources =
            normalizeSourceWeights(
                weightedSources
            );

        const fusedProbability =
            normalizedSources.reduce(
                (
                    accumulator,
                    source
                ) =>
                    accumulator +
                    source.probability *
                    source.normalizedWeight,
                0
            );

        return {

            probability:
                clampPercentage(
                    fusedProbability,
                    0
                ),

            sources:
                normalizedSources,

            activeSourceCount:
                normalizedSources.length

        };
    }

    /* ======================================================================
     * SECTION 42
     * Source Agreement Engine
     * ====================================================================== */

    function calculateSourceAgreement(
        fusedSources = []
    ) {

        if (
            !Array.isArray(
                fusedSources
            ) ||
            fusedSources.length === 0
        ) {
            return 0;
        }

        if (
            fusedSources.length === 1
        ) {
            return 45;
        }

        const probabilities =
            fusedSources.map(
                (source) =>
                    source.probability
            );

        const deviation =
            calculateStandardDeviation(
                probabilities
            );

        return clampPercentage(
            100 -
            deviation *
            1.6,
            0
        );
    }

    /* ======================================================================
     * SECTION 43
     * Forecast Confidence Engine
     * ====================================================================== */

    function calculateForecastConfidence(
        fusionResult,
        horizonHours
    ) {

        const horizonKey =
            getForecastHorizonKey(
                horizonHours
            );

        const sources =
            fusionResult?.sources ??
            [];

        if (
            sources.length === 0
        ) {
            return 0;
        }

        const agreement =
            calculateSourceAgreement(
                sources
            );

        const weightedQuality =
            calculateWeightedAverage(
                sources.map(
                    (source) => ({

                        value:
                            source.quality,

                        weight:
                            source.normalizedWeight

                    })
                )
            );

        const weightedSourceConfidence =
            calculateWeightedAverage(
                sources.map(
                    (source) => ({

                        value:
                            source.confidence,

                        weight:
                            source.normalizedWeight

                    })
                )
            );

        const sourceCoverage =
            clampPercentage(
                (
                    sources.length /
                    Object.keys(
                        DEFAULT_SOURCE_WEIGHTS
                    ).length
                ) *
                100,
                0
            );

        const confidenceDecay =
            FORECAST_CONFIDENCE_DECAY[
                horizonKey
            ] ?? 0;

        let confidence =
            agreement *
                0.35 +

            weightedQuality *
                0.25 +

            weightedSourceConfidence *
                0.25 +

            sourceCoverage *
                0.15 -

            confidenceDecay;

        const simulatedSourceCount =
            sources.filter(
                (source) =>
                    source.simulated ===
                    true
            ).length;

        if (
            simulatedSourceCount >
            sources.length / 2
        ) {
            confidence -=
                15;
        }

        const minimumConfidence =
            FORECAST_MINIMUM_CONFIDENCE[
                horizonKey
            ] ?? 15;

        if (
            sources.length >=
            DEFAULT_SOURCE_FUSION_CONFIGURATION
                .minimumSources
        ) {

            confidence =
                Math.max(
                    confidence,
                    minimumConfidence
                );
        }

        return clampPercentage(
            confidence,
            0
        );
    }

    /* ======================================================================
     * SECTION 44
     * Rainfall Accumulation Fusion
     * ====================================================================== */

    function calculateForecastRainfallAmount(
        sources = {},
        horizonHours = 6,
        probability = 0
    ) {

        const weightedAmounts =
            [];

        for (
            const sourceKey of
            Object.keys(
                DEFAULT_SOURCE_WEIGHTS
            )
        ) {

            const source =
                sources[
                    sourceKey
                ];

            if (
                !source ||
                !normalizeSourceAvailability(
                    source
                )
            ) {
                continue;
            }

            const amount =
                extractSourceRainfallAmount(
                    source,
                    horizonHours
                );

            const weight =
                calculateDynamicSourceWeight(
                    sourceKey,
                    source,
                    horizonHours
                );

            if (
                amount <= 0 ||
                weight <= 0
            ) {
                continue;
            }

            weightedAmounts.push({

                value:
                    amount,

                weight

            });
        }

        let rainfallAmount =
            calculateWeightedAverage(
                weightedAmounts
            );

        const probabilityFactor =
            clampPercentage(
                probability,
                0
            ) /
            100;

        rainfallAmount *=
            probabilityFactor;

        return Math.max(
            0,
            roundNumber(
                rainfallAmount,
                2
            )
        );
    }

    /* ======================================================================
     * SECTION 45
     * Rain Intensity Classification
     * ====================================================================== */

    function classifyRainIntensity(
        rainfallMm
    ) {

        const amount =
            Math.max(
                0,
                toFiniteNumber(
                    rainfallMm,
                    0
                )
            );

        if (
            amount <
            RAINFALL_ACCUMULATION_THRESHOLDS_MM
                .TRACE
        ) {
            return RAIN_INTENSITY_LEVELS.NONE;
        }

        if (
            amount <
            RAINFALL_ACCUMULATION_THRESHOLDS_MM
                .LIGHT
        ) {
            return RAIN_INTENSITY_LEVELS.TRACE;
        }

        if (
            amount <
            RAINFALL_ACCUMULATION_THRESHOLDS_MM
                .MODERATE
        ) {
            return RAIN_INTENSITY_LEVELS.LIGHT;
        }

        if (
            amount <
            RAINFALL_ACCUMULATION_THRESHOLDS_MM
                .HEAVY
        ) {
            return RAIN_INTENSITY_LEVELS.MODERATE;
        }

        if (
            amount <
            RAINFALL_ACCUMULATION_THRESHOLDS_MM
                .VERY_HEAVY
        ) {
            return RAIN_INTENSITY_LEVELS.HEAVY;
        }

        if (
            amount <
            RAINFALL_ACCUMULATION_THRESHOLDS_MM
                .EXTREME
        ) {
            return RAIN_INTENSITY_LEVELS.VERY_HEAVY;
        }

        return RAIN_INTENSITY_LEVELS.EXTREME;
    }

    /* ======================================================================
     * SECTION 46
     * Forecast Decision Classification
     * ====================================================================== */

    function classifyForecastDecision(
        probability,
        confidence,
        activeSourceCount
    ) {

        const normalizedProbability =
            clampPercentage(
                probability,
                0
            );

        const normalizedConfidence =
            clampPercentage(
                confidence,
                0
            );

        if (
            activeSourceCount <
            DEFAULT_SOURCE_FUSION_CONFIGURATION
                .minimumSources
        ) {
            return FORECAST_DECISIONS
                .INSUFFICIENT_DATA;
        }

        if (
            normalizedProbability >=
                RAIN_PROBABILITY_THRESHOLDS
                    .HIGH &&
            normalizedConfidence >=
                55
        ) {
            return FORECAST_DECISIONS
                .RAIN_EXPECTED;
        }

        if (
            normalizedProbability >=
                RAIN_PROBABILITY_THRESHOLDS
                    .LIKELY
        ) {
            return FORECAST_DECISIONS
                .RAIN_LIKELY;
        }

        if (
            normalizedProbability >=
                RAIN_PROBABILITY_THRESHOLDS
                    .POSSIBLE
        ) {
            return FORECAST_DECISIONS
                .RAIN_POSSIBLE;
        }

        if (
            normalizedProbability >=
                RAIN_PROBABILITY_THRESHOLDS
                    .VERY_LOW
        ) {
            return FORECAST_DECISIONS
                .LOW_PROBABILITY;
        }

        return FORECAST_DECISIONS
            .NO_RAIN_EXPECTED;
    }

    /* ======================================================================
     * SECTION 47
     * Risk Calculation
     * ====================================================================== */

    function calculateForecastRisk(
        probability,
        rainfallMm,
        confidence,
        sources = []
    ) {

        const normalizedProbability =
            clampPercentage(
                probability,
                0
            );

        const normalizedConfidence =
            clampPercentage(
                confidence,
                0
            );

        const amountScore =
            clampPercentage(
                (
                    Math.max(
                        0,
                        rainfallMm
                    ) /
                    RAINFALL_ACCUMULATION_THRESHOLDS_MM
                        .EXTREME
                ) *
                100,
                0
            );

        const lightningSource =
            sources.find(
                (source) =>
                    source.sourceKey ===
                    "lightning"
            );

        const lightningBonus =
            lightningSource
                ? lightningSource.probability *
                    0.10
                : 0;

        const risk =
            normalizedProbability *
                0.50 +

            amountScore *
                0.30 +

            normalizedConfidence *
                0.20 +

            lightningBonus;

        return clampPercentage(
            risk,
            0
        );
    }

    function classifyRiskLevel(
        risk
    ) {

        const normalizedRisk =
            clampPercentage(
                risk,
                0
            );

        if (
            normalizedRisk >=
            RISK_THRESHOLDS
                .EXTREME
        ) {
            return RISK_LEVELS
                .EXTREME;
        }

        if (
            normalizedRisk >=
            RISK_THRESHOLDS
                .SEVERE
        ) {
            return RISK_LEVELS
                .SEVERE;
        }

        if (
            normalizedRisk >=
            RISK_THRESHOLDS
                .HIGH
        ) {
            return RISK_LEVELS
                .HIGH;
        }

        if (
            normalizedRisk >=
            RISK_THRESHOLDS
                .MODERATE
        ) {
            return RISK_LEVELS
                .MODERATE;
        }

        if (
            normalizedRisk >=
            RISK_THRESHOLDS
                .LOW
        ) {
            return RISK_LEVELS
                .LOW;
        }

        return RISK_LEVELS
            .NONE;
    }

    /* ======================================================================
     * SECTION 48
     * Forecast Uncertainty
     * ====================================================================== */

    function calculateForecastUncertainty(
        fusionResult,
        confidence,
        horizonHours
    ) {

        const sources =
            fusionResult?.sources ??
            [];

        const probabilities =
            sources.map(
                (source) =>
                    source.probability
            );

        const sourceSpread =
            calculateStandardDeviation(
                probabilities
            );

        const horizonFactor =
            normalizeForecastHorizon(
                horizonHours
            ) /
            72;

        const confidencePenalty =
            100 -
            clampPercentage(
                confidence,
                0
            );

        const uncertainty =
            sourceSpread *
                0.45 +

            horizonFactor *
                100 *
                0.35 +

            confidencePenalty *
                0.20;

        return clampPercentage(
            uncertainty,
            0
        );
    }

    /* ======================================================================
     * SECTION 49
     * Forecast Trend Calculation
     * ====================================================================== */

    function calculateForecastTrend(
        previousProbability,
        currentProbability
    ) {

        const previous =
            clampPercentage(
                previousProbability,
                currentProbability
            );

        const current =
            clampPercentage(
                currentProbability,
                previous
            );

        const difference =
            current -
            previous;

        if (
            difference >= 20
        ) {
            return FORECAST_TRENDS
                .RAPIDLY_INCREASING;
        }

        if (
            difference >= 7
        ) {
            return FORECAST_TRENDS
                .INCREASING;
        }

        if (
            difference <= -20
        ) {
            return FORECAST_TRENDS
                .RAPIDLY_DECREASING;
        }

        if (
            difference <= -7
        ) {
            return FORECAST_TRENDS
                .DECREASING;
        }

        return FORECAST_TRENDS
            .STABLE;
    }

    /* ======================================================================
     * SECTION 50
     * Single Horizon Forecast Builder
     * ====================================================================== */

    function buildHorizonForecast({
        city,
        sources,
        horizonHours,
        previousProbability = null,
        language = "ar"
    }) {

        const normalizedHorizon =
            normalizeForecastHorizon(
                horizonHours
            );

        const horizonKey =
            getForecastHorizonKey(
                normalizedHorizon
            );

        const fusionResult =
            calculateFusedRainProbability(
                sources,
                normalizedHorizon
            );

        const probability =
            fusionResult.probability;

        const confidence =
            calculateForecastConfidence(
                fusionResult,
                normalizedHorizon
            );

        const rainfallMm =
            calculateForecastRainfallAmount(
                sources,
                normalizedHorizon,
                probability
            );

        const intensity =
            classifyRainIntensity(
                rainfallMm
            );

        const decision =
            classifyForecastDecision(
                probability,
                confidence,
                fusionResult.activeSourceCount
            );

        const risk =
            calculateForecastRisk(
                probability,
                rainfallMm,
                confidence,
                fusionResult.sources
            );

        const riskLevel =
            classifyRiskLevel(
                risk
            );

        const uncertainty =
            calculateForecastUncertainty(
                fusionResult,
                confidence,
                normalizedHorizon
            );

        const trend =
            previousProbability ===
                null
                ? FORECAST_TRENDS
                    .UNKNOWN
                : calculateForecastTrend(
                    previousProbability,
                    probability
                );

        return {

            horizon:
                normalizedHorizon,

            horizonKey,

            label:
                getForecastHorizonLabel(
                    normalizedHorizon,
                    language
                ),

            city:
                city?.name ??
                city?.city ??
                city?.cityName ??
                "Unknown",

            cityId:
                city?.cityId ??
                city?.id ??
                null,

            probability:
                roundNumber(
                    probability,
                    1
                ),

            expectedRain:
                probability >=
                EXPECTED_RAIN_THRESHOLD,

            rainfallMm:
                roundNumber(
                    rainfallMm,
                    2
                ),

            intensity,

            confidence:
                roundNumber(
                    confidence,
                    1
                ),

            uncertainty:
                roundNumber(
                    uncertainty,
                    1
                ),

            risk:
                roundNumber(
                    risk,
                    1
                ),

            riskLevel,

            decision,

            trend,

            activeSourceCount:
                fusionResult
                    .activeSourceCount,

            sourceContributions:
                fusionResult
                    .sources
                    .map(
                        (source) => ({

                            sourceKey:
                                source.sourceKey,

                            probability:
                                roundNumber(
                                    source.probability,
                                    1
                                ),

                            quality:
                                roundNumber(
                                    source.quality,
                                    1
                                ),

                            confidence:
                                roundNumber(
                                    source.confidence,
                                    1
                                ),

                            weight:
                                roundNumber(
                                    source.normalizedWeight,
                                    4
                                ),

                            simulated:
                                source.simulated

                        })
                    ),

            forecastTime:
                new Date(
                    Date.now() +
                    normalizedHorizon *
                    MILLISECONDS_PER_HOUR
                ).toISOString(),

            generatedAt:
                new Date()
                    .toISOString()

        };
    }

