        /* ==================================================================
         * SECTION 275
         * Build National Forecast Quality Summary
         * ================================================================== */

        buildNationalForecastQualitySummary(
            trendSummary = {},
            reliabilitySummary = null
        ) {

            const reliability =
                reliabilitySummary ??
                this.buildNationalReliabilitySummary(
                    trendSummary
                );

            const qualityScore =
                this.calculateNationalForecastQualityScore(
                    trendSummary,
                    reliability
                );

            const qualityLevel =
                this.classifyNationalForecastQuality(
                    qualityScore
                );

            const factors =
                reliability?.factors ??
                {};

            const lowQualityFactors =
                Object.entries(
                    {

                        confidence:
                            toFiniteNumber(
                                factors.confidenceScore,
                                0
                            ),

                        dataQuality:
                            toFiniteNumber(
                                factors.dataQualityScore,
                                0
                            ),

                        uncertainty:
                            toFiniteNumber(
                                factors.invertedUncertaintyScore,
                                0
                            ),

                        consistency:
                            toFiniteNumber(
                                factors.consistencyScore,
                                0
                            ),

                        stability:
                            toFiniteNumber(
                                factors.stabilityScore,
                                0
                            )
                    }
                )
                    .filter(
                        (
                            [
                                ,
                                value
                            ]
                        ) =>
                            value <
                            55
                    )
                    .sort(
                        (
                            first,
                            second
                        ) =>
                            first[1] -
                            second[1]
                    )
                    .map(
                        (
                            [
                                name,
                                value
                            ]
                        ) => ({

                            name,

                            score:
                                roundNumber(
                                    value,
                                    2
                                ),

                            critical:
                                value <
                                30
                        })
                    );

            const strengths =
                Object.entries(
                    {

                        confidence:
                            toFiniteNumber(
                                factors.confidenceScore,
                                0
                            ),

                        dataQuality:
                            toFiniteNumber(
                                factors.dataQualityScore,
                                0
                            ),

                        uncertainty:
                            toFiniteNumber(
                                factors.invertedUncertaintyScore,
                                0
                            ),

                        consistency:
                            toFiniteNumber(
                                factors.consistencyScore,
                                0
                            ),

                        stability:
                            toFiniteNumber(
                                factors.stabilityScore,
                                0
                            )
                    }
                )
                    .filter(
                        (
                            [
                                ,
                                value
                            ]
                        ) =>
                            value >=
                            70
                    )
                    .sort(
                        (
                            first,
                            second
                        ) =>
                            second[1] -
                            first[1]
                    )
                    .map(
                        (
                            [
                                name,
                                value
                            ]
                        ) => ({

                            name,

                            score:
                                roundNumber(
                                    value,
                                    2
                                )
                        })
                    );

            return {

                available:
                    trendSummary?.available ===
                    true,

                qualityScore,

                qualityLevel,

                qualityLabel:
                    this.getNationalForecastQualityLabel(
                        qualityLevel
                    ),

                reliabilityScore:
                    reliability
                        .reliabilityScore,

                reliabilityLevel:
                    reliability
                        .reliabilityLevel,

                lowQualityFactors,

                strengths,

                limitingFactor:
                    lowQualityFactors[0] ??
                    null,

                strongestFactor:
                    strengths[0] ??
                    null,

                operationallyUsable:
                    qualityScore >=
                        50 &&
                    reliability
                        .reliabilityScore >=
                        50,

                suitableForAlerts:
                    qualityScore >=
                        65 &&
                    reliability
                        .reliabilityScore >=
                        60,

                suitableForCriticalAlerts:
                    qualityScore >=
                        78 &&
                    reliability
                        .reliabilityScore >=
                        72 &&
                    trendSummary
                        ?.conflicting !==
                        true,

                requiresVerification:
                    qualityScore <
                        55 ||
                    reliability
                        .requiresCaution ===
                        true,

                degraded:
                    qualityLevel ===
                    "DEGRADED",

                generatedAt:
                    this.getNowISO()
            };
        }

