        normalizeNationalResponseResourceCategory(
            category
        ) {

            const normalizedCategory =
                String(
                    category ??
                    "FIELD_RESPONSE_TEAMS"
                )
                    .trim()
                    .toUpperCase()
                    .replace(
                        /[\s-]+/g,
                        "_"
                    );

            const aliases = {

                COMMAND:
                    "COMMAND_AND_CONTROL",

                CONTROL:
                    "COMMAND_AND_CONTROL",

                LEADERSHIP:
                    "COMMAND_AND_CONTROL",

                PERSONNEL:
                    "EMERGENCY_PERSONNEL",

                STAFF:
                    "EMERGENCY_PERSONNEL",

                EMERGENCY_STAFF:
                    "EMERGENCY_PERSONNEL",

                FIELD_TEAMS:
                    "FIELD_RESPONSE_TEAMS",

                RESPONSE_TEAMS:
                    "FIELD_RESPONSE_TEAMS",

                MEDICAL:
                    "MEDICAL_SUPPORT",

                HEALTH_SUPPORT:
                    "MEDICAL_SUPPORT",

                AMBULANCE:
                    "MEDICAL_SUPPORT",

                RESCUE:
                    "RESCUE_AND_EVACUATION",

                EVACUATION:
                    "RESCUE_AND_EVACUATION",

                VEHICLES:
                    "TRANSPORT_AND_MOBILITY",

                TRANSPORT:
                    "TRANSPORT_AND_MOBILITY",

                MOBILITY:
                    "TRANSPORT_AND_MOBILITY",

                COMMUNICATION:
                    "COMMUNICATION_SYSTEMS",

                TELECOMMUNICATION:
                    "COMMUNICATION_SYSTEMS",

                RADIO_SYSTEMS:
                    "COMMUNICATION_SYSTEMS",

                SENSORS:
                    "MONITORING_AND_SENSORS",

                MONITORING:
                    "MONITORING_AND_SENSORS",

                RADAR:
                    "MONITORING_AND_SENSORS",

                FLOOD:
                    "FLOOD_CONTROL",

                PUMPS:
                    "FLOOD_CONTROL",

                DRAINAGE:
                    "FLOOD_CONTROL",

                UTILITIES:
                    "POWER_AND_UTILITIES",

                POWER:
                    "POWER_AND_UTILITIES",

                ELECTRICITY:
                    "POWER_AND_UTILITIES",

                SHELTER:
                    "SHELTER_AND_RELIEF",

                RELIEF:
                    "SHELTER_AND_RELIEF",

                FOOD_AND_WATER:
                    "SHELTER_AND_RELIEF",

                LOGISTICS:
                    "LOGISTICS_AND_SUPPLY",

                SUPPLY:
                    "LOGISTICS_AND_SUPPLY",

                WAREHOUSING:
                    "LOGISTICS_AND_SUPPLY",

                MEDIA:
                    "PUBLIC_INFORMATION",

                PUBLIC_COMMUNICATION:
                    "PUBLIC_INFORMATION",

                INFORMATION:
                    "PUBLIC_INFORMATION",

                TECHNICAL:
                    "TECHNICAL_SUPPORT",

                IT_SUPPORT:
                    "TECHNICAL_SUPPORT",

                SYSTEM_SUPPORT:
                    "TECHNICAL_SUPPORT"
            };

            const resolvedCategory =
                aliases[
                    normalizedCategory
                ] ??
                normalizedCategory;

            const validCategories =
                Object.values(
                    this.getNationalResponseResourceCategories()
                );

            return validCategories.includes(
                resolvedCategory
            )
                ? resolvedCategory
                : "FIELD_RESPONSE_TEAMS";
        }

