        getNationalFieldMissionStates() {

            return {

                CREATED:
                    "CREATED",

                PENDING_APPROVAL:
                    "PENDING_APPROVAL",

                APPROVED:
                    "APPROVED",

                ASSIGNED:
                    "ASSIGNED",

                MOBILIZING:
                    "MOBILIZING",

                EN_ROUTE:
                    "EN_ROUTE",

                ON_SITE:
                    "ON_SITE",

                IN_PROGRESS:
                    "IN_PROGRESS",

                PAUSED:
                    "PAUSED",

                BLOCKED:
                    "BLOCKED",

                PARTIALLY_COMPLETED:
                    "PARTIALLY_COMPLETED",

                COMPLETED:
                    "COMPLETED",

                VERIFIED:
                    "VERIFIED",

                FAILED:
                    "FAILED",

                CANCELLED:
                    "CANCELLED",

                EXPIRED:
                    "EXPIRED"
            };
        }

        normalizeNationalFieldMissionState(
            state
        ) {

            const normalizedState =
                String(
                    state ??
                    "CREATED"
                )
                    .trim()
                    .toUpperCase()
                    .replace(
                        /[\s-]+/g,
                        "_"
                    );

            const aliases = {

                NEW:
                    "CREATED",

                DRAFT:
                    "CREATED",

                WAITING_APPROVAL:
                    "PENDING_APPROVAL",

                AWAITING_APPROVAL:
                    "PENDING_APPROVAL",

                AUTHORIZED:
                    "APPROVED",

                AUTHORISED:
                    "APPROVED",

                ALLOCATED:
                    "ASSIGNED",

                DISPATCHED:
                    "MOBILIZING",

                DEPLOYING:
                    "MOBILIZING",

                TRAVELLING:
                    "EN_ROUTE",

                TRAVELING:
                    "EN_ROUTE",

                ARRIVED:
                    "ON_SITE",

                ACTIVE:
                    "IN_PROGRESS",

                EXECUTING:
                    "IN_PROGRESS",

                SUSPENDED:
                    "PAUSED",

                DELAYED:
                    "BLOCKED",

                PARTIAL:
                    "PARTIALLY_COMPLETED",

                DONE:
                    "COMPLETED",

                CLOSED:
                    "VERIFIED",

                ERROR:
                    "FAILED",

                CANCELED:
                    "CANCELLED",

                TIMEOUT:
                    "EXPIRED"
            };

            const resolvedState =
                aliases[
                    normalizedState
                ] ??
                normalizedState;

            const validStates =
                Object.values(
                    this.getNationalFieldMissionStates()
                );

            return validStates.includes(
                resolvedState
            )
                ? resolvedState
                : "CREATED";
        }

