        getNationalIncidentCommandLevels() {

            return {

                LOCAL_COMMAND:
                    "LOCAL_COMMAND",

                MUNICIPAL_COMMAND:
                    "MUNICIPAL_COMMAND",

                REGIONAL_COMMAND:
                    "REGIONAL_COMMAND",

                UNIFIED_REGIONAL_COMMAND:
                    "UNIFIED_REGIONAL_COMMAND",

                NATIONAL_COMMAND:
                    "NATIONAL_COMMAND",

                NATIONAL_UNIFIED_COMMAND:
                    "NATIONAL_UNIFIED_COMMAND",

                NATIONAL_CRISIS_COMMAND:
                    "NATIONAL_CRISIS_COMMAND"
            };
        }

        normalizeNationalIncidentCommandLevel(
            commandLevel
        ) {

            const normalizedLevel =
                String(
                    commandLevel ??
                    "LOCAL_COMMAND"
                )
                    .trim()
                    .toUpperCase()
                    .replace(
                        /[\s-]+/g,
                        "_"
                    );

            const aliases = {

                LOCAL:
                    "LOCAL_COMMAND",

                FIELD:
                    "LOCAL_COMMAND",

                SITE_COMMAND:
                    "LOCAL_COMMAND",

                CITY:
                    "MUNICIPAL_COMMAND",

                MUNICIPAL:
                    "MUNICIPAL_COMMAND",

                GOVERNORATE:
                    "REGIONAL_COMMAND",

                REGION:
                    "REGIONAL_COMMAND",

                REGIONAL:
                    "REGIONAL_COMMAND",

                UNIFIED_REGION:
                    "UNIFIED_REGIONAL_COMMAND",

                REGIONAL_UNIFIED:
                    "UNIFIED_REGIONAL_COMMAND",

                NATIONAL:
                    "NATIONAL_COMMAND",

                CENTRAL_COMMAND:
                    "NATIONAL_COMMAND",

                UNIFIED_NATIONAL:
                    "NATIONAL_UNIFIED_COMMAND",

                NATIONAL_UNIFIED:
                    "NATIONAL_UNIFIED_COMMAND",

                CRISIS:
                    "NATIONAL_CRISIS_COMMAND",

                NATIONAL_CRISIS:
                    "NATIONAL_CRISIS_COMMAND",

                EMERGENCY_COMMAND:
                    "NATIONAL_CRISIS_COMMAND"
            };

            const resolvedLevel =
                aliases[
                    normalizedLevel
                ] ??
                normalizedLevel;

            const validLevels =
                Object.values(
                    this.getNationalIncidentCommandLevels()
                );

            return validLevels.includes(
                resolvedLevel
            )
                ? resolvedLevel
                : "LOCAL_COMMAND";
        }

        getNationalIncidentCommandLevelLabel(
            commandLevel,
            language = null
        ) {

            const normalizedLevel =
                this.normalizeNationalIncidentCommandLevel(
                    commandLevel
                );

            const resolvedLanguage =
                String(
                    language ??
                    this.language ??
                    "ar"
                )
                    .trim()
                    .toLowerCase() ===
                    "en"
                    ? "en"
                    : "ar";

            const labels = {

                ar: {

                    LOCAL_COMMAND:
                        "القيادة الميدانية المحلية",

                    MUNICIPAL_COMMAND:
                        "قيادة المدينة أو المحافظة",

                    REGIONAL_COMMAND:
                        "القيادة الإقليمية",

                    UNIFIED_REGIONAL_COMMAND:
                        "القيادة الإقليمية الموحدة",

                    NATIONAL_COMMAND:
                        "القيادة الوطنية",

                    NATIONAL_UNIFIED_COMMAND:
                        "القيادة الوطنية الموحدة",

                    NATIONAL_CRISIS_COMMAND:
                        "القيادة الوطنية للأزمات"
                },

                en: {

                    LOCAL_COMMAND:
                        "Local field command",

                    MUNICIPAL_COMMAND:
                        "Municipal or governorate command",

                    REGIONAL_COMMAND:
                        "Regional command",

                    UNIFIED_REGIONAL_COMMAND:
                        "Unified regional command",

                    NATIONAL_COMMAND:
                        "National command",

                    NATIONAL_UNIFIED_COMMAND:
                        "National unified command",

                    NATIONAL_CRISIS_COMMAND:
                        "National crisis command"
                }
            };

            return (
                labels[
                    resolvedLanguage
                ][
                    normalizedLevel
                ] ??
                labels[
                    resolvedLanguage
                ].LOCAL_COMMAND
            );
        }

