getNationalIncidentCommandRecoveryClosureStatusDefinitions() {
    return Object.freeze({
        NOT_READY: Object.freeze({
            id: "NOT_READY",
            terminal: false,
            closed: false
        }),

        PENDING_AUTHORIZATION: Object.freeze({
            id: "PENDING_AUTHORIZATION",
            terminal: false,
            closed: false
        }),

        AUTHORIZED: Object.freeze({
            id: "AUTHORIZED",
            terminal: false,
            closed: false
        }),

        TRANSITION_IN_PROGRESS: Object.freeze({
            id: "TRANSITION_IN_PROGRESS",
            terminal: false,
            closed: false
        }),

        CONDITIONALLY_CLOSED: Object.freeze({
            id: "CONDITIONALLY_CLOSED",
            terminal: true,
            closed: true
        }),

        FULLY_CLOSED: Object.freeze({
            id: "FULLY_CLOSED",
            terminal: true,
            closed: true
        }),

        CLOSURE_REJECTED: Object.freeze({
            id: "CLOSURE_REJECTED",
            terminal: true,
            closed: false
        }),

        CLOSURE_REVOKED: Object.freeze({
            id: "CLOSURE_REVOKED",
            terminal: true,
            closed: false
        })
    });
}

